// =============================================================
// Node: Exchange Code for Short-Lived Token
// Instagram Basic Display API / Graph API OAuth
// =============================================================
//
// Incoming body fields:
//   code          — authorisation code from Instagram
//   state         — base64 JSON containing { email }
//   member_email  — extracted email (may come from state)
//   redirect_uri  — must match app settings exactly
//
// IMPORTANT: Use $env.INSTAGRAM_APP_SECRET (not getCredentials)
// =============================================================

const body = $input.item.json.body || $input.item.json;

const code         = body.code;
const memberEmail  = body.member_email || '';
const redirectUri  = body.redirect_uri || 'https://brief.one-empire.com/instagram/callback';

const appId     = '1278647270579382';
const appSecret = $env.INSTAGRAM_APP_SECRET;

if (!code) throw new Error('Missing authorisation code');
if (!appSecret) throw new Error('INSTAGRAM_APP_SECRET not set in environment');

// Step 1: Exchange code for short-lived token (valid 1 hour)
const shortTokenRes = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.instagram.com/oauth/access_token',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({
    client_id:     appId,
    client_secret: appSecret,
    grant_type:    'authorization_code',
    redirect_uri:  redirectUri,
    code:          code
  }).toString()
});

if (!shortTokenRes.access_token) {
  throw new Error('Short-lived token exchange failed: ' + JSON.stringify(shortTokenRes));
}

const shortToken   = shortTokenRes.access_token;
const instagramId  = shortTokenRes.user_id;

// Step 2: Exchange for long-lived token (valid 60 days)
const longTokenRes = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://graph.instagram.com/access_token',
  qs: {
    grant_type:        'ig_exchange_token',
    client_secret:     appSecret,
    access_token:      shortToken
  }
});

if (!longTokenRes.access_token) {
  throw new Error('Long-lived token exchange failed: ' + JSON.stringify(longTokenRes));
}

const longToken = longTokenRes.access_token;
const expiresIn = longTokenRes.expires_in || 5184000; // default 60 days in seconds

// Step 3: Fetch Instagram user profile
const profileRes = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://graph.instagram.com/me',
  qs: {
    fields:       'id,username,name',
    access_token: longToken
  }
});

const now          = new Date();
const expiresAt    = new Date(now.getTime() + expiresIn * 1000);

return [{
  json: {
    member_email:       memberEmail,
    instagram_id:       profileRes.id || instagramId,
    instagram_username: profileRes.username || '',
    instagram_name:     profileRes.name || profileRes.username || '',
    access_token:       longToken,
    expires_in:         expiresIn,
    token_stored_at:    now.toISOString(),
    token_expires_at:   expiresAt.toISOString()
  }
}];

// =============================================================
// Node: Store Instagram Token in Supabase
// Upserts on member_email — updates token if already linked
// =============================================================

const data = $input.item.json;

const supabaseUrl = 'https://gsqcsyepztcmrvzxevhw.supabase.co';
const serviceKey  = $env.SUPABASE_SERVICE_KEY;

if (!serviceKey) throw new Error('SUPABASE_SERVICE_KEY not set');

const payload = {
  member_email:       data.member_email,
  instagram_id:       data.instagram_id,
  instagram_username: data.instagram_username,
  instagram_name:     data.instagram_name,
  access_token:       data.access_token,
  expires_in:         data.expires_in,
  token_stored_at:    data.token_stored_at,
  token_expires_at:   data.token_expires_at,
  is_active:          true,
  updated_at:         new Date().toISOString()
};

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: supabaseUrl + '/rest/v1/instagram_tokens',
  headers: {
    'apikey':        serviceKey,
    'Authorization': 'Bearer ' + serviceKey,
    'Content-Type':  'application/json',
    'Prefer':        'resolution=merge-duplicates'
  },
  body: JSON.stringify(payload)
});

return [{
  json: {
    success: true,
    instagram_name: data.instagram_name,
    instagram_username: data.instagram_username,
    member_email: data.member_email,
    token_expires_at: data.token_expires_at
  }
}];
